<script setup lang="ts">
import type {DateInfo} from '../../../../shared/contracts';
const props=defineProps<{modelValue:DateInfo}>();const emit=defineEmits<{ 'update:modelValue':[DateInfo] }>();
function precision(event:Event){const p=(event.target as HTMLSelectElement).value as DateInfo['precision'];emit('update:modelValue',{precision:p,value:null,fromYear:null,toYear:null,approximate:false,note:props.modelValue.note});}
function change(key:keyof DateInfo,value:unknown){emit('update:modelValue',{...props.modelValue,[key]:value});}
</script>
<template><fieldset><legend>记录日期</legend><p class="muted">这是原稿日期，与上传时间分开；不确定就保留不确定。</p><div class="fields"><label>日期精度<select :value="modelValue.precision" @change="precision"><option value="unknown">日期待确认</option><option value="year">只知道年份</option><option value="month">知道年月</option><option value="day">确定年月日</option><option value="range">年份范围</option></select></label><label v-if="['year','month','day'].includes(modelValue.precision)">日期值<input :value="modelValue.value" :placeholder="modelValue.precision==='year'?'例如 2007':modelValue.precision==='month'?'例如 2007-08':'例如 2007-08-12'" @input="change('value',($event.target as HTMLInputElement).value||null)"></label><template v-if="modelValue.precision==='range'"><label>开始年份<input type="number" min="1" max="9999" :value="modelValue.fromYear" @input="change('fromYear',($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null)"></label><label>结束年份<input type="number" min="1" max="9999" :value="modelValue.toYear" @input="change('toYear',($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null)"></label></template></div><label v-if="modelValue.precision!=='unknown'" class="check"><input type="checkbox" :checked="modelValue.approximate" @change="change('approximate',($event.target as HTMLInputElement).checked)">约略日期（显示“约”）</label><label>日期不确定说明<input :value="modelValue.note" maxlength="200" placeholder="例如：原稿未写日期，可能是 2007 或 2008 年" @input="change('note',($event.target as HTMLInputElement).value||null)"></label></fieldset></template>
<style scoped>fieldset{border:1px solid var(--line);border-radius:10px;padding:16px;margin:20px 0;min-width:0}.fields{display:flex;flex-wrap:wrap;gap:16px}label{display:grid;gap:6px;margin:10px 0;min-width:0}.fields label{flex:1;min-width:140px}.check{display:flex;align-items:center}p{margin-top:0}</style>
